import json

def transform_debug(grid):
    H, W = len(grid), len(grid[0])
    color = 5
    output = [row[:] for row in grid]

    shape_cells = set((r, c) for r in range(H) for c in range(W) if output[r][c] == color)

    if not shape_cells:
        return output

    visited = set()
    components = []
    for r in range(H):
        for c in range(W):
            if (r, c) in shape_cells and (r, c) not in visited:
                comp = set()
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    comp.add((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if (nr, nc) in shape_cells and (nr, nc) not in visited:
                            stack.append((nr, nc))
                components.append(comp)

    print(f"Found {len(components)} components")
    for i, comp in enumerate(components):
        min_r, max_r = min(r for r,c in comp), max(r for r,c in comp)
        min_c, max_c = min(c for r,c in comp), max(c for r,c in comp)
        print(f"  Component {i}: rows {min_r}-{max_r}, cols {min_c}-{max_c}")

    for comp_idx, comp in enumerate(components):
        min_r, max_r = min(r for r,c in comp), max(r for r,c in comp)
        min_c, max_c = min(c for r,c in comp), max(c for r,c in comp)

        top_gap_row = None
        top_gap_col = None

        for r in range(min_r, max_r + 1):
            row_5s = [c for c in range(min_c, max_c + 1) if output[r][c] == color]
            if row_5s:
                full_range = range(min(row_5s), max(row_5s) + 1)

                gap_exists = False
                gap_col = None
                for c in full_range:
                    if output[r][c] == 0:
                        gap_exists = True
                        gap_col = c
                        break

                if gap_exists and top_gap_row is None:
                    top_gap_row = r
                    top_gap_col = gap_col
                    print(f"  Component {comp_idx}: top gap at row {r}, col {gap_col}")

        print(f"  Component {comp_idx}: will draw line at row {top_gap_row - 1 if top_gap_row else None}, cols 0-{top_gap_col if top_gap_col else None}")

        if top_gap_row is not None and top_gap_col is not None:
            line_row = top_gap_row - 1
            if line_row >= 0:
                for c in range(top_gap_col + 1):
                    output[line_row][c] = 2

        # Fill ALL gaps
        for r in range(min_r, max_r + 1):
            row_5s = [c for c in range(min_c, max_c + 1) if output[r][c] == color]
            if row_5s:
                for c in range(min(row_5s), max(row_5s) + 1):
                    if output[r][c] == 0:
                        output[r][c] = 2

    return output

